// El id de WhatsApp es el celular salvo con BSUID; nunca se fija a mano (H-05).
const uid = String($user.get('id') || '');
const dig = uid.replace(/\D/g, '');
let cel = '';
if (/^5939\d{8}$/.test(dig)) cel = '0' + dig.slice(3);
else if (/^09\d{8}$/.test(dig)) cel = dig;
$memory.set('id_whatsapp', uid);
$memory.set('celular_canal', cel);
$memory.set('celular', cel);
$memory.set('ahora_iso', new Date().toISOString());
$memory.set('terminos_version', 'v1');
// PROVISIONAL hasta recibir los links del cliente ([C] 1dfg0rkn7d2).
$memory.set('link_terminos', '[link de términos pendiente]');
$memory.set('link_politica', '[link de política de datos pendiente]');

