configuration.content:
let vigente = 'no';
try {
  const j = $context.getHttpResponse('consResp').json();
  const r = (j.items || [])[0];
  if (r && r.decision === 'acepto' && r.version === $memory.get('terminos_version')) {
    const dias = (Date.now() - new Date(r.fecha).getTime()) / 86400000;
    if (dias <= 30) vigente = 'si';
  }
} catch (e) { vigente = 'no'; }
$memory.set('consentimiento_vigente', vigente);

const d = String($memory.get('celular_ingresado') || '').replace(/\D/g, '');
let c = '';
if (/^09\d{8}$/.test(d)) c = d; else if (/^5939\d{8}$/.test(d)) c = '0' + d.slice(3); else if (/^9\d{8}$/.test(d)) c = '0' + d;
$memory.set('celular', c);

// Meta inyecta $memory._referral cuando la conversación viene de un anuncio click-to-WhatsApp
// (docs.jelou.ai › Integraciones › Meta Ads). Si no existe, la conversación llegó directo.
let ref = null;
try { ref = $memory.getJson('_referral', null); } catch (e) { ref = null; }
const o = ref || {};
const desdeAnuncio = !!(ref && (o.source_id || o.source_url || o.ctwa_clid));
$memory.set('origen_plataforma', desdeAnuncio ? 'meta_' + String(o.source_type || 'ad') : 'directo');
$memory.set('origen_pagina', String(o.source_url || ''));
$memory.set('origen_anuncio', String(o.source_id || ''));
$memory.set('origen_campana', '');
$memory.set('origen_grupo', '');
$memory.set('origen_formulario', '');
$memory.set('origen_ctwa_clid', String(o.ctwa_clid || ''));
$memory.set('origen_texto', desdeAnuncio
  ? ('Anuncio Meta ' + String(o.source_id || '') + ' ' + String(o.source_url || '') + ' (ctwa ' + String(o.ctwa_clid || '') + '): ' + String(o.body || '').slice(0, 300)).trim()
  : 'directo');

const result = $memory.getJson('bienvenidaResult', {});
let accion = String(result.accion || '').toLowerCase();
const intencion = String(result.intencion || '').toLowerCase();
const marca = String(result.marca || '');
// Sin acción válida, o ventas sin marca confirmada, va a un asesor (RN-04).
if (!['ventas', 'derivar', 'sin_interes'].includes(accion)) accion = 'derivar';
const consulta = String(result.consulta || '').trim().slice(0, 200);
// Búsqueda directa: ventas puede seguir sin marca si hay una consulta (modelo o características).
if (accion === 'ventas' && !/^\d+$/.test(marca) && !consulta) accion = 'derivar';
$memory.set('consulta_vehiculo', accion === 'ventas' ? consulta : '');
$memory.set('accion_enrutamiento', accion);
$memory.set('marca_seleccionada', marca);
$memory.set('marca_nombre', String(result.marca_nombre || ''));
$memory.set('intencion_seleccionada', intencion || (accion === 'ventas' ? 'comercial' : 'asesor'));
$memory.set('motivo_derivacion', accion === 'derivar' ? (intencion || 'asesor') : '');

let tiene = 'no';
try {
  const j = $context.getHttpResponse('asesorResp').json();
  if (j.tipo === 'ok' && j.data) {
    tiene = 'si';
    $memory.set('asesor_nombre', String(j.data.nombre || ''));
    $memory.set('asesor_celular', String(j.data.celular || ''));
    $memory.set('asesor_correo', String(j.data.correo || ''));
    $memory.set('asesor_agencia', String(j.data.agencia || ''));
  }
} catch (e) { tiene = 'no'; }
$memory.set('tiene_asesor', tiene);
